// Turn a messy call transcript into a request for Gemini to write a clean job description.
const transcript = ($input.first().json['Call transcript'] || '').trim();
if (transcript.length < 200) {
  throw new Error('The transcript is empty or too short. Paste the whole call.');
}

const instructions = `You turn a messy recruiter-client call transcript into a clean job description
for a remote-staffing agency. The recruiter will review it before anything is sent.

Rules:
- Use only facts from the transcript. Never invent requirements, salary, hours or dates. Use "" or [] when not stated.
- When the client changes their mind, use the FINAL decision, and mention the change in recruiter_notes.
- must_haves: only what the client called required. nice_to_haves: what they called a plus or bonus.
- not_required: things the client explicitly ruled out (e.g. "No payroll"), so nobody screens on them.
- Keep each list item short (under 15 words). Write in clear, friendly English.`;

const schema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    client_company: { type: 'string' },
    client_location: { type: 'string' },
    summary: { type: 'string' },
    responsibilities: { type: 'array', items: { type: 'string' } },
    must_haves: { type: 'array', items: { type: 'string' } },
    nice_to_haves: { type: 'array', items: { type: 'string' } },
    not_required: { type: 'array', items: { type: 'string' } },
    salary: { type: 'string' },
    schedule: { type: 'string' },
    start_date: { type: 'string' },
    recruiter_notes: { type: 'array', items: { type: 'string' } }
  },
  required: ['title', 'client_company', 'client_location', 'summary', 'responsibilities', 'must_haves',
             'nice_to_haves', 'not_required', 'salary', 'schedule', 'start_date', 'recruiter_notes'],
  additionalProperties: false
};

return [{
  json: {
    body: {
      model: 'gemini-3.5-flash-lite',
      system_instruction: instructions,
      input: [{ type: 'text', text: 'Call transcript:\n\n' + transcript }],
      response_format: { type: 'text', mime_type: 'application/json', schema: schema }
    }
  }
}];

// Read Gemini's job description and format it for Slack and for the database.
const reply = $input.first().json;

let jd = null;
let problem = '';
try {
  if (reply.error) throw new Error(typeof reply.error === 'string' ? reply.error : (reply.error.description || reply.error.message || 'API error'));
  if (reply.status && reply.status !== 'completed') throw new Error('Gemini did not finish: ' + reply.status);
  const steps = reply.steps || [];
  const output = steps.filter(s => s.type === 'model_output').pop() || steps[steps.length - 1];
  const textPart = ((output && output.content) || []).find(c => c.type === 'text');
  jd = JSON.parse(textPart ? textPart.text : reply.output_text);
} catch (e) {
  problem = e.message;
}
// Stop loudly instead of saving a broken job description.
if (!jd) throw new Error('Could not write the job description: ' + problem);

const bullets = list => (list && list.length ? list.map(x => '• ' + x).join('\n') : '• (none stated)');

const text = [
  `*${jd.title}*: ${jd.client_company}${jd.client_location ? ' (' + jd.client_location + ')' : ''}`,
  '',
  jd.summary,
  '',
  '*Must-haves*', bullets(jd.must_haves),
  '',
  '*Nice-to-haves*', bullets(jd.nice_to_haves),
  ...(jd.not_required.length ? ['', '*Not required*', bullets(jd.not_required)] : []),
  '',
  '*What they will do*', bullets(jd.responsibilities),
  '',
  `*Salary:* ${jd.salary || 'not stated'}`,
  `*Schedule:* ${jd.schedule || 'not stated'}`,
  `*Start:* ${jd.start_date || 'not stated'}`,
  ...(jd.recruiter_notes.length ? ['', '_Recruiter notes:_', bullets(jd.recruiter_notes)] : [])
].join('\n');

return [{ json: { ...jd, job_description: text } }];

